def _reply_question_end(reply, qdcount):
    """按 qdcount 从偏移 12 起界定问题段结束位置；无法界定返回 None。"""
    pos = _MIN_MESSAGE_LEN
    for _ in range(qdcount):
        while True:
            if pos >= len(reply):
                return None
            length = reply[pos]
            kind = length & 0xC0
            if kind == 0xC0:
                if pos + 1 >= len(reply):
                    return None
                pos += 2
                break
            if kind != 0x00:
                return None
