                raise EncodeError("opt option truncated")
            opt_len = int.from_bytes(response[rdata + 2:rdata + 4], "big")
            rdata += 4
            if rdata + opt_len > opt_end:
                raise EncodeError("opt option data truncated")
            rdata += opt_len
